window.ScripturaLexicons.BDAG_PART_0254 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-01\" data-source=\"BDAG\" data-search=\"ὁλοτελῶς advérbio inteiramente; completamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁλοτελῶς</td><td>advérbio</td><td>inteiramente; completamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-02\" data-source=\"BDAG\" data-search=\"Ὀλοφέρνης, ου, ὁ nome próprio masculino Holofernes; comandante assírio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ὀλοφέρνης, ου, ὁ</td><td>nome próprio masculino</td><td>Holofernes; comandante assírio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-03\" data-source=\"BDAG\" data-search=\"Ὀλυμπᾶς, ᾶ, ὁ nome próprio masculino Olimpas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ὀλυμπᾶς, ᾶ, ὁ</td><td>nome próprio masculino</td><td>Olimpas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-04\" data-source=\"BDAG\" data-search=\"ὄλυνθος, ου, ὁ substantivo masculino figo tardio; figo de verão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄλυνθος, ου, ὁ</td><td>substantivo masculino</td><td>figo tardio; figo de verão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-05\" data-source=\"BDAG\" data-search=\"ὅλως advérbio completamente; realmente; de fato BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅλως</td><td>advérbio</td><td>completamente; realmente; de fato</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-06\" data-source=\"BDAG\" data-search=\"ὁμαλίζω verbo tornar plano; nivelar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμαλίζω</td><td>verbo</td><td>tornar plano; nivelar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-07\" data-source=\"BDAG\" data-search=\"ὁμαλός, ή, όν adjetivo plano; liso; nivelado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμαλός, ή, όν</td><td>adjetivo</td><td>plano; liso; nivelado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-08\" data-source=\"BDAG\" data-search=\"ὁμαλῶς advérbio suavemente; uniformemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμαλῶς</td><td>advérbio</td><td>suavemente; uniformemente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-09\" data-source=\"BDAG\" data-search=\"ὄμβρος, ου, ὁ substantivo masculino tempestade de chuva; temporal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄμβρος, ου, ὁ</td><td>substantivo masculino</td><td>tempestade de chuva; temporal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-10\" data-source=\"BDAG\" data-search=\"ὁμείρομαι verbo ansiar; desejar ardentemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμείρομαι</td><td>verbo</td><td>ansiar; desejar ardentemente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-11\" data-source=\"BDAG\" data-search=\"ὁμιλέω verbo conversar; falar; dirigir-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμιλέω</td><td>verbo</td><td>conversar; falar; dirigir-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-12\" data-source=\"BDAG\" data-search=\"ὁμιλία, ας, ἡ substantivo feminino companhia; convivência; discurso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμιλία, ας, ἡ</td><td>substantivo feminino</td><td>companhia; convivência; discurso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-13\" data-source=\"BDAG\" data-search=\"ὅμιλος, ου, ὁ substantivo masculino multidão; aglomeração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅμιλος, ου, ὁ</td><td>substantivo masculino</td><td>multidão; aglomeração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-14\" data-source=\"BDAG\" data-search=\"ὁμίχλη, ης, ἡ substantivo feminino névoa; neblina BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμίχλη, ης, ἡ</td><td>substantivo feminino</td><td>névoa; neblina</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-15\" data-source=\"BDAG\" data-search=\"ὄμμα, ατος, τό substantivo neutro olho; percepção espiritual BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄμμα, ατος, τό</td><td>substantivo neutro</td><td>olho; percepção espiritual</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-16\" data-source=\"BDAG\" data-search=\"ὀμνύω verbo jurar; prestar juramento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀμνύω</td><td>verbo</td><td>jurar; prestar juramento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-17\" data-source=\"BDAG\" data-search=\"ὁμοήθεια, ας, ἡ substantivo feminino semelhança de caráter; concordância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμοήθεια, ας, ἡ</td><td>substantivo feminino</td><td>semelhança de caráter; concordância</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-18\" data-source=\"BDAG\" data-search=\"ὁμοθυμαδόν advérbio unanimemente; juntos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμοθυμαδόν</td><td>advérbio</td><td>unanimemente; juntos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-19\" data-source=\"BDAG\" data-search=\"ὁμοιάζω verbo ser semelhante; parecer-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμοιάζω</td><td>verbo</td><td>ser semelhante; parecer-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0254-20\" data-source=\"BDAG\" data-search=\"ὁμοιοπαθής, ές adjetivo da mesma natureza; de sentimentos semelhantes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμοιοπαθής, ές</td><td>adjetivo</td><td>da mesma natureza; de sentimentos semelhantes</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0254-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁλοτελῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁλοτελῶς</span>, advérbio de <span class=\"greek\">ὁλοτελής</span> (Petosiris, Fgm. 21 linha 260; Peripl. Eryth. 30; Vett. Val. 155, 3; Dt 13:16 [17] Aq.), inteiramente, completamente: <span class=\"greek\">μετανοεῖν</span>, arrepender-se plenamente, Hv 3, 13, 4a.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ὀλοφέρνης, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ὀλοφέρνης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>, Holofernes, comandante supremo assírio, morto por Judite em sua própria tenda, quando cercava Betúlia, cidade natal dela (Jdth 2ff), 1 Cl 55:5.—Sobre o nome e a pessoa de H., ver JMarquart, Philol. 54, 1895, 507ff; Pauly-W. VIII 1167–71; Schürer III/1, 216–18.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ὀλυμπᾶς, ᾶ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ὀλυμπᾶς</span>, <span class=\"greek\">ᾶ</span>, <span class=\"greek\">ὁ</span> (IG III 1080, 28.—CIL XIV 1286. Etimologia incerta, mas ver W-S. §16, 9; Rouffiac 91), Olimpas, destinatário de saudação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:15</a>. As variantes de leitura <span class=\"greek\">Ὀλυμπίδα</span> e Olympiadem provavelmente resultam de erro de um copista latino.—LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄλυνθος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄλυνθος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hes. e outros; Theophr., Caus. Pl. 5, 9, 12; Diosc. 1, 185; SSol 2:13; vocábulo de empréstimo na literatura rabínica), figo tardio, figo de verão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:13</a>. VHehn, Kulturpflanzen u. Haustiere 8 1911, 95ff; RAC VII 641, 675.—DELG. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅλως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅλως</span>, advérbio de <span class=\"greek\">ὅλος</span> (Pla. e posteriores). ① Marcador do grau máximo numa escala de extensão, completamente, inteiramente, por toda parte. <span class=\"greek\">ὅλως</span> <span class=\"greek\">ἀκούεται</span>, comenta-se por toda parte = é de conhecimento geral, é assunto de toda a cidade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:1</a> (cf. AFridrichsen, Symb Osl 13, ’34, 43f: «dizer logo de uma vez»; Diod S 13, 16, 2: «continuamente», «repetidas vezes»; Ps.-Demetr., El. cap. 175; 199 R.: <span class=\"greek\">ὅλως</span> = «regularmente», «em geral», «por toda parte», podendo ocorrer em paralelo com <span class=\"greek\">παντοδαποῦ</span>; para outra interpretação, ver 2 abaixo); <span class=\"greek\">ἤδη</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ὅλως</span> <span class=\"greek\">ἥττημα</span>, de fato, é uma derrota completa, 6:7 (REB: «Com efeito, sofreis derrota»; para outra interpretação, ver 2 abaixo). Com bastante frequência, acompanhado de negação: de modo nenhum (X., Mem. 1, 2, 35; Dio Chrys. 53 [70], 5; 8; Philostrat., Vi. Apoll. 1, 39 p. 41, 9; Philo, Op. M. 170, Praem. 40; Jos., Vi. 221, Ant. 8, 241; TestJud 16:3; Ar. 11, 7; Just., A I, 16, 5; 43, 2 e outros; Ath. 1, 2; 4, 1): <span class=\"greek\">μὴ</span> <span class=\"greek\">ὅλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:34</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:29</a>; Hv 4, 1, 9; m 4, 2, 1 e outros. Totalmente, por completo: <span class=\"greek\">κατέλιπον</span> <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, abandonaram completamente o caminho de Deus, ApcPt Bodl. ② Relativo ao que realmente ocorre, com a implicação de ser geralmente conhecido, realmente, de fato (POxy 1676, 31 [III d.C.] <span class=\"greek\">καλῶς</span> <span class=\"greek\">ποιήσεις</span> <span class=\"greek\">ἐλθούσα</span> … <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">ὅ</span>. <span class=\"greek\">ἴδωμέν</span> <span class=\"greek\">σε</span> = «farás um favor ao vir … até nós, para que realmente possamos ver-te»): <span class=\"greek\">ὅλως</span> <span class=\"greek\">ἀκούεται</span>, «de fato se noticia» (NRSV), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:1</a>. <span class=\"greek\">ὅλως</span> <span class=\"greek\">ἥττημα</span>, «já é uma derrota» (NRSV), 6:7. Para a interpretação alternativa dessas passagens, ver 1 acima.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμαλίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμαλίζω</span> (<span class=\"greek\">ὁμαλός</span>), futuro ático <span class=\"greek\">ὁμαλιῶ</span> (X. e outros; SIG 313, 10; 22; PTebt 375, 30; LXX; PsSol 8:17), tornar plano, nivelar: <span class=\"greek\">ὄρη</span>, montanhas, 11:4 (Is 45:2).—DELG s.v. <span class=\"greek\">ὁμός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμαλός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμαλός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">ὁμός</span>; cf. <span class=\"greek\">ἅμα</span>; Hom. e outros; inscrições; PCairZen 769, 6 [III a.C.]; Aq., Sym., Theod., Philo; Ath., R. 16, 67, 17). ① Relativo a uma superfície uniformemente plana, plano, liso, nivelado, em sentido literal: <span class=\"greek\">ὁμαλὸν</span> <span class=\"greek\">γίνεσθαι</span>, tornar-se plano, Hs 9, 10, 1; <span class=\"greek\">τὰ</span> <span class=\"greek\">ὁμ</span>., o terreno plano, v 1, 1, 3. ② Relativo à ausência de desvios, para o comportamento correto ou a facilidade de execução, plano, em extensão figurada de 1: <span class=\"greek\">τῇ</span> <span class=\"greek\">ὀρθῇ</span> <span class=\"greek\">ὁδῷ</span> <span class=\"greek\">πορεύεσθαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁμ</span>., andar pelo caminho reto e plano, Hm 6, 1, 2. <span class=\"greek\">πάντα</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">γίνεται</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐκλεκτοῖς</span>, todas as coisas se tornarão fáceis para os eleitos (dele), v 1, 3, 4; cf. m 2:4 (com <span class=\"greek\">ἱλαρός</span>).—DELG s.v. <span class=\"greek\">ὁμό</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμαλῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμαλῶς</span>, advérbio de <span class=\"greek\">ὁμαλός</span> (Thu. e outros; Ath., R. 11 p. 63, 2), suavemente, uniformemente: <span class=\"greek\">ὁμ</span>. <span class=\"greek\">περιπατεῖν</span>, caminhar sem tropeços, Hm 6, 1, 4.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄμβρος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄμβρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom. e outros; inscrições, também IAndrosIsis, Kyme 54; papiros, LXX, En, Philo; Jos., Ant. 1, 101; 2, 343 e outros), tempestade de chuva, temporal com trovões, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:54</a>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμείρομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμείρομαι</span> (também <span class=\"greek\">ἱμείρομαι</span>, variante de leitura, mas provavelmente sem relação etimológica; ver DELG; CIG III 4000, 7 [IV d.C.] <span class=\"greek\">ὁμειρόμενοι</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">παιδός</span> [Ramsay, JHS 38, 1918, 157; 160]; Job 3:21 <span class=\"greek\">οἳ</span> <span class=\"greek\">ὁμείρονται</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span> [variante de leitura <span class=\"greek\">ἱμείρ</span>.]; Ps 62:2 Sym. Hesíquio explica-o por <span class=\"greek\">ἐπιθυμεῖν</span>.—Thackeray 97; GMilligan, Exp. 9th Ser. II 1924, 227f), sentir desejo ardente, ansiar, com <span class=\"greek\">τινός</span>, por alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:8</a> (W-H. escrevem <span class=\"greek\">ὀμ</span>. [ver Schwyzer I 715 n. 10], ver aparato 152; Mlt-H. 251; ADebrunner, IndogF 21, 1907, 203f; W-S. §16, 6; B-D-F § 101 p. 53f; sobre a construção, ver §171, 1; Rob. 508).—DELG <span class=\"greek\">ὀμείρομαι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμιλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμιλέω</span> (<span class=\"greek\">ὅμιλος</span>), imperfeito <span class=\"greek\">ὡμίλουν</span>; futuro, 3ª pessoa do singular, <span class=\"greek\">ὁμιλήσει</span>, Pr 15:12; 1 aoristo <span class=\"greek\">ὡμίλησα</span>; infinitivo perfeito <span class=\"greek\">ὡμιληκέναι</span>, Just., D. 62, 2 (Hom. e posteriores; significado primário «estar em companhia de» alguém e depois «conversar»): estar em grupo e falar, falar, conversar, dirigir-se (Hom., Pla. e outros; LXX. Cf. nosso uso de «encontrar-se» no sentido de «ter uma discussão» sobre algo), com <span class=\"greek\">τινί</span>, com alguém (Philemo Com. 169 K. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">γυνὴ</span> <span class=\"greek\">γυναικὶ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἰδίαν</span> <span class=\"greek\">ὁμιλεῖ</span>; Ael. Aristid. 28, 116 K.=49 p. 529 D.: <span class=\"greek\">θεῷ</span>; POxy 928, 5 <span class=\"greek\">ὡμείλησας</span> <span class=\"greek\">δέ</span> <span class=\"greek\">μοί</span> <span class=\"greek\">ποτε</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τούτου</span>; Da 1:19; GrBar 7:3; ApcMos 16; Jos., Ant. 17, 50; Just., D. 59, 1 e outros.—Sobre a íntima associação de Deus com o Logos: <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">πάντος</span> <span class=\"greek\">ὁμιλῶν</span>, Theoph. Ant. 2, 22 [p. 154, 20]): <span class=\"greek\">ὡμίλει</span> <span class=\"greek\">αὐτῷ</span>, costumava falar com ele, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:26</a> (Himerius, Or. 48 [=Or. 14], 18 <span class=\"greek\">ὁμ</span>. <span class=\"greek\">τινι</span> = conferenciar com alguém). Sobre Cristo falando aos mártires (cf. Herm. Wr. 12, 19 [<span class=\"greek\">τῷ</span> <span class=\"greek\">ἀνθρώπῳ</span>] <span class=\"greek\">μόνῳ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὁμιλεῖ</span>): <span class=\"greek\">παρεστὼς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">ὡμίλει</span> <span class=\"greek\">αὐτοῖς</span>, o Senhor permanecia junto deles e conversava com eles, MPol 2:2. Também com <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> (X., Mem. 4, 3, 2; Jos., Ant. 11, 260 <span class=\"greek\">τούτων</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἀλλήλους</span> <span class=\"greek\">ὁμιλούντων</span>): <span class=\"greek\">ὡμίλουν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἀλλήλους</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">πάντων</span>, conversavam uns com os outros sobre todas as coisas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:14</a>. Com acusativo de coisa: <span class=\"greek\">οὐ</span> <span class=\"greek\">ξένα</span> <span class=\"greek\">ὁμιλῶ</span>, nada de estranho tenho a dizer, Dg 11:1. <span class=\"greek\">ἃ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">ὁμιλεῖ</span>, 11:7. Uso absoluto (Diod S 13, 83, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:15</a>. <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἱκανὸν</span> <span class=\"greek\">ὁμιλήσας</span> <span class=\"greek\">ἄχρι</span> <span class=\"greek\">αὐγῆς</span>, depois de falar por longo tempo até o amanhecer, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:11</a>.—RAC IX, 1100–45.—DELG s.v. <span class=\"greek\">ὅμιλο</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμιλία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμιλία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὅμιλος</span>). Tal como o verbo, este substantivo se refere inicialmente a um grupo e, depois, ao que seus membros costumam fazer: conversar (escólio a Soph., El. 420: <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁμιλία</span> <span class=\"greek\">λέγεται</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">συνουσίας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">διαλέξεως</span>, «o termo <span class=\"greek\">ὁ</span>. é usado tanto para associação quanto para conversa»). ① Estado de estreita associação entre pessoas, convivência, relacionamento social, companhia (autores trágicos, Thu. e posteriores; X., Mem. 1, 2, 20 <span class=\"greek\">ὁμιλία</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">χρηστῶν</span>; Herm. Wr. em Stob. I 277, 21 W.=432, 20 Sc. <span class=\"greek\">τὰς</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πολλοὺς</span> <span class=\"greek\">ὁμιλίας</span> <span class=\"greek\">παραιτοῦ</span>; PTebt 703, 273f [III a.C.]; POxy 471, 76; PYadin 15, 6; 22: ver nota do editor p. 63; Wsd 8:18; 3 Macc 5:18; TestAbr B 2 p. 107, 4 [Stone p. 62]; Jos., Ant. 11, 34, Vi. 67; Tat. 26, 4; Ath. 22, 4 <span class=\"greek\">ὁμιλίαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἄρρενος</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θῆλυ</span>): <span class=\"greek\">ὁμιλίαι</span> <span class=\"greek\">κακαί</span>, más companhias, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:33</a> (ver <span class=\"greek\">ἦθος</span> e também EpArist 130). ② Ato de falar, quer como conversa (assim Diod S 16, 55, 2; segundo Moeris [276f=203f P.], o termo helenístico é <span class=\"greek\">λαλιά</span>, ver esse verbete), quer como discurso ou preleção a um grupo (Ael. Aristid. 42, 9 K.=6 p. 68 D.; Lucian, Demon. 12; Philostrat., Vi. Apoll. 3, 15 p. 93, 20, Imag. Prooem. p. 295, 11; Dositheus 1, 1; TestSol D 4, 14; TestAbr A 5 p. 82, 4 [Stone p. 12]; Jos., Ant. 15, 68; Ps.-Clem., Hom. p. 6, 28; 12, 11; 28 e outros, Lag.). Este último sentido, discurso, preleção, aparece em nossa literatura a propósito da apresentação de um monólogo diante de uma congregação: <span class=\"greek\">ὁμιλίαν</span> <span class=\"greek\">ποιεῖσθαι</span>, proferir um sermão, pregar (como Just., D. 28, 2; 85, 5.—Quanto a <span class=\"greek\">ὁμ</span>. <span class=\"greek\">ποιεῖσθαι</span>, cf. Jos., Vi. 222), com <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, sobre algo, IPol 5:1.—DELG s.v. <span class=\"greek\">ὅμιλο</span>. M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅμιλος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅμιλος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ὁμός</span>, «comum, compartilhado», <span class=\"greek\">ἵλη</span>, «grupo»; Hom. e outros; 1 Km 19:20 Aq.; Philo, Agr. 23), multidão, aglomeração: <span class=\"greek\">πᾶς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πλοίων</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὅμ</span>., toda a multidão (dos que viajavam) nos navios, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:17</a>, variante de leitura (ver Charles, ICC Rv ad loc.; Jos., Ant. 5, 17 <span class=\"greek\">ὁ</span> <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὅμιλος</span>).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμίχλη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμίχλη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (a forma etimologicamente correta é <span class=\"greek\">ὀμίχλη</span>, assim em Hom.; Schwyzer I 411; DELG; B. 66; L-S-J-M <span class=\"greek\">ὀμίχλη</span>) (Hom. e outros; Plut., Mor. 460a; Ael. Aristid. 51, 19 K.=27 p. 539 D.; PGM 4, 3024; LXX, En; SibOr 3, 806), condição atmosférica que escurece o céu (mas não tão densa quanto <span class=\"greek\">νέφος</span> ou <span class=\"greek\">νεφέλη</span>, Aristot., Mete. 346b, 33), névoa, neblina; plural <span class=\"greek\">ὁμίχλαι</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">λαίλαπος</span> <span class=\"greek\">ἐλαυνόμεναι</span>, névoas impelidas pela tempestade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:17</a> (com <span class=\"greek\">ζόφος</span> e <span class=\"greek\">σκότος</span>, como Lucian, Catapl. 2).—B. 66. Schmidt, Syn. I 611–15. DELG s.v. <span class=\"greek\">ὀμίχλη</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄμμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄμμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (Hom. e posteriores, mais comum na poesia do que na prosa; SIG 1168, 120; PLond III, 678, 6 p. 18 [99/98 a.C.]; BGU 713, 9; PGM 4, 703; LXX; En 106:5; 10; TestSol; Jos., Bell. 6, 288). ① Órgão da visão corporal, olho, em sentido literal, plural (Diod S 3, 46, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:23</a>. ② Meio de percepção transcendente, olho, extensão figurada de 1: <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄμμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span>, olho da alma (Pla., Rep. 7, 533d, Soph. 254a; Porphyr., Vi. Pyth. 47; Philo, Sacr. Abel. 36, Abr. 70.—PGM 4, 517 <span class=\"greek\">ἀθανάτοις</span> <span class=\"greek\">ὄμμασι</span>; 3, 474.—Rtzst., Mysterienrel. 3 296f; 318f): <span class=\"greek\">ἐμβλέπειν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὄμμ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, olhar para algo com os olhos da alma, 1 Cl 19:3.—B. 225. DELG s.v. <span class=\"greek\">ὄπωπα</span> B. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀμνύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀμνύω</span> (forma variante de <span class=\"greek\">ὄμνυμι</span>, predominante no grego helenístico e, portanto, também no NT; na forma <span class=\"greek\">ὄμνυμι</span>, Hom. e outros; inscrições, papiros; Just.; a forma variante em Hdt., X. e outros; inscrições, papiros, LXX, En, Philo; Jos., Ant. 3, 271, C. Ap. 2, 121. No NT, a forma mais antiga ocorre apenas no infinitivo <span class=\"greek\">ὀμνύναι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.71\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:71</a> [variante de leitura <span class=\"greek\">ὀμνύειν</span>]; B-D-F § 92; W-S. §14, 8; Mlt-H. 251), 1 aoristo <span class=\"greek\">ὤμοσα</span>; perfeito <span class=\"greek\">ὀμώμοκα</span>, LXX: afirmar a veracidade da própria declaração invocando uma entidade transcendente, frequentemente com convite implícito à punição caso se fale falsamente, jurar, prestar juramento. Com acusativo de pessoa ou coisa pela qual se jura (Hom. e outros; X., An. 7, 6, 18; Diod S 1, 29, 4 <span class=\"greek\">τὴν</span> <span class=\"greek\">῏Ισιν</span>; Appian, Syr. 60 §317 <span class=\"greek\">πάντας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεούς</span>, Bell. Civ. 4, 68, §289; UPZ 70, 2 [152/151 a.C.] <span class=\"greek\">τὸν</span> <span class=\"greek\">Σάραπιν</span>; POxy 239, 5 [66 d.C.] <span class=\"greek\">Νέρωνα</span>; B-D-F § 149; Rob. 484. Sobre a LXX, ver Johannessohn, Kasus 77; Jos., Ant. 5, 14; 13, 76; Orig., Hippol.): <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανόν</span>, <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span>, jurar pelo céu, pela terra (Apollon. Rhod. 3, 699 e escólio sobre Apollon. Rhod. 3, 714 <span class=\"greek\">ὄμοσον</span> <span class=\"greek\">Γαῖάν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Οὐρανόν</span>; cf. <span class=\"greek\">διομνύω</span> Aesop, Fab. 140 H.=89 P.//91 [I, III] H-H.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:12</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">Καίσαρος</span> <span class=\"greek\">τύχην</span>, MPol 9:2; 10:1. Emprego absoluto, no mesmo sentido (cf. Jos., Ant. 4, 310), 9:3; (com <span class=\"greek\">ἐπιθῦσαι</span>) MPol 4.—Em lugar do acusativo, usa-se <span class=\"greek\">ἐν</span> com dativo de pessoa ou coisa (como <span class=\"hebrew\" dir=\"rtl\">נִשְׁבַּע</span> <span class=\"hebrew\" dir=\"rtl\">בְּ</span> no AT; <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span>, En 5:6; ver Johannessohn, loc. cit.): <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οὐρανῷ</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">γῇ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:34</a>–35 (cf. a recomendação contrária, 1QS 5, 8; MDelcor, VetusT 16, ’66, 8–25 [céu e terra]); cf. 23:22 (GHeinrici, Beiträge III 1905, 42–5; ERietschel, Das Verbot des Eides in d. Bergpredigt: StKr 79, 1906, 373–418; ibid. 80, 1907, 609–18; OProksch, Das Eidesverbot Jesu Christi: Thüringer kirchl. Jahrbuch 1907; HMüller, Zum Eidesverbot d. Bergpred. 1913; OOlivieri, Biblica 4, 1923, 385–90; GStählin, Zum Gebrauch von Beteuerungsformeln im NT, NovT 5, ’62, 115–43; Billerb. I 321–36; ULuz, Mt, tradução WLinss ’89 [’85], 311–22.—Advertência contra todo e qualquer juramento já em Choerilus Epicus [V a.C.] Fgm. 7 K.=10 B.: Stob., Flor. 3, 27, 1 vol. III p. 611, 3 H. <span class=\"greek\">ὅρκον</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">οὔτ</span>’ <span class=\"greek\">ἄδικον</span> <span class=\"greek\">χρεὼν</span> <span class=\"greek\">ὀμνύναι</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">δίκαιον</span>; Nicol. Dam.: 90 Fgm. 103i Jac.: os frígios não juram de modo algum; pitagóricos segundo Diog. L. 8, 22; essênios em Jos., Bell. 2, 135; cf. Soph., Oed. Col. 650f: basta a palavra de um homem bom; analogamente Aeschyl., Fgm. 394 TGF p. 114; ver também Plut., Mor. 275c). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κεφαλῇ</span> <span class=\"greek\">σου</span>, pela tua cabeça, 5:36. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ναῷ</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">χρυσῷ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ναοῦ</span>, 23:16; 21. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θυσιαστηρίῳ</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">δώρῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐπάνω</span>, versículos 18, 20. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ζῶντι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αἰῶνας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αἰώνων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:6</a>. <span class=\"greek\">ἐν</span> é substituído por <span class=\"greek\">εἰς</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:35</a> (B-D-F § 206, 2). Também <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>, por alguém ou algo (Aristoph.; Demosth. [exemplos em FBleek, Hb II/2, 1840, 245a]; Longus, Past. 4, 20, 2; Porphyr., Abst. 3, 16; Ps.-Lucian, Calumn. 18; SIG 526, 8; 685, 27; BGU 248, 12 [I d.C.]; Gen 22:16; 31:53; Ex 32:13; 1 Km 30:15; Am 6:8; Zeph 1:5): <span class=\"greek\">ἐπεὶ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">οὐδενὸς</span> <span class=\"greek\">εἶχεν</span> <span class=\"greek\">μείζονος</span> <span class=\"greek\">ὀμόσαι</span>, <span class=\"greek\">ὤμοσεν</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἑαυτοῦ</span>, já que (Deus) não tinha ninguém maior por quem jurar, jurou por si mesmo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:13</a>; cf. versículo 16 (Philo, Leg. All. 3, 203 <span class=\"greek\">οὐ</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἑτέρου</span> <span class=\"greek\">ὀμνύει</span> <span class=\"greek\">θεός</span>, <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">κρεῖττον</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἑαυτοῦ</span>, <span class=\"greek\">ὅς</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ἄριστος</span>, De Abr. 273; sobre o assunto, cf. Hom., Il. 1, 524–27). <span class=\"greek\">ὤμοσεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">δεσπότης</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δόξης</span> <span class=\"greek\">αὐτοῦ</span>, o Senhor jurou por sua glória, Hv 2, 2, 5. Afirma-se mesmo que Deus <span class=\"greek\">ὤμ</span>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">αὐτοῦ</span>, v 2, 2, 8. Seguido de discurso direto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:21</a> (Ps 109:4). O discurso direto é precedido por <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.74\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:74</a> (com <span class=\"greek\">καταθεματίζειν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.71\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:71</a> (com <span class=\"greek\">ἀναθεματίζειν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:6f</a>. Como citação de Ps 94:11, com <span class=\"greek\">εἰ</span> antes do discurso direto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:11</a>; 4:3 (ver <span class=\"greek\">εἰ</span> 4).—Com dativo de pessoa, confirmar algo (<span class=\"greek\">τὶ</span>) a alguém por juramento, 6:8 (Ex 33:1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:17</a>, variante de leitura (<span class=\"greek\">ἧς</span> por atração, em lugar de <span class=\"greek\">ἥν</span>). Seguido de infinitivo (Just., A I, 21, 3 <span class=\"greek\">ὀμνύντα</span> … <span class=\"greek\">ἑωρακέναι</span>): <span class=\"greek\">τίσιν</span> <span class=\"greek\">ὤμοσεν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εἰσελεύσεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κατάπαυσιν</span> <span class=\"greek\">αὐτοῦ</span>;, a quem assegurou por juramento que não entrariam no seu descanso?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:18</a> (dativo com infinitivo futuro, como Plut., Galba 1063 [22, 12]). <span class=\"greek\">διαθήκη</span> <span class=\"greek\">ἣν</span> <span class=\"greek\">ὤμοσεν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πατράσι</span> <span class=\"greek\">δοῦναι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λαῷ</span>, a aliança que ele jurou aos pais dar ao povo, 14:1. Seguido de discurso direto introduzido pelo <span class=\"greek\">ὅτι</span> recitativo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:23</a> (JDerrett, Law in the NT, ’70, 339–58). <span class=\"greek\">ὅρκῳ</span> <span class=\"greek\">ὀμ</span>. <span class=\"greek\">τινί</span>, com infinitivo subsequente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:30</a>. Embora o dativo <span class=\"greek\">ὅρκῳ</span> seja raro nessa combinação (cf. En 6:4; TestJud 22:3), o acusativo (Hom. e outros; Gen 26:3; Num 30:3) é bastante comum: <span class=\"greek\">ὅρκον</span> <span class=\"greek\">ὀμ</span>. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> (<span class=\"greek\">ὀμ</span>. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>, Od. 14, 331; 19, 288), prestar juramento a alguém, seguido de genitivo do infinitivo aoristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.73\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:73</a>.—RHirzel, D. Eid 1902; LWenger, D. Eid in d. griech. pap: ZSavRG, Rom. Abt. 23, 1902, 158ff; JPedersen, Der Eid bei den Semiten 1914; ESeidl, Der Eid in röm.-ägypt. Provinzialrecht, ’33.—B. 1437. DELG s.v. <span class=\"greek\">ὄμνυμι</span>. M-M. TRE IX, 379–82. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμοήθεια, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμοήθεια</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὁμός</span>, «um e o mesmo, comum», <span class=\"greek\">ἦθος</span>, «caráter»; Nicol. Dam.: 90 Fgm. 139 Jac.; Philostrat., Vi. Apoll. 2, 11 p. 53, 11; Pollux 3, 62), semelhança de caráter, concordância de convicções: <span class=\"greek\">ὁμοήθειαν</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">λαβόντες</span>, vós que recebestes concordância divina de convicções, IMg 6:2. <span class=\"greek\">κατὰ</span> <span class=\"greek\">ὁμοήθειαν</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">λαλεῖν</span>, falar com base numa unidade divina de convicções, IPol 1:3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμοθυμαδόν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμοθυμαδόν</span> (<span class=\"greek\">ὁμός</span>, «um e o mesmo, comum», <span class=\"greek\">θυμός</span>, e terminação adverbial), advérbio (Aristoph., X. e outros; sobre sua formação, ver Kühner-Bl. II 307 <span class=\"greek\">γ</span>; Schwyzer I 626; Mlt-H. 164), com uma só mente, propósito ou impulso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:14</a>; 2:1, variante de leitura, 46; 4:24; 7:57; 8:6; 12:20; 18:12; 19:29; 20:18, variante de leitura; MPol 12:3. (Com <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑνὶ</span> <span class=\"greek\">στόματι</span>) <span class=\"greek\">δοξάζειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, glorificar a Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:6</a>; <span class=\"greek\">γενόμενοι</span> <span class=\"greek\">ὁμ</span>., tendo chegado a um acordo unânime, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:25</a>. O significado enfraquecido juntos (NRSV e outros) é provável em 5:12 e em outros lugares (assim EHatch, Essays in Biblical Greek, 1889, 63f; HCadbury, JBL 44, 1925, 216–18; NRSV e outros).—DELG s.v. <span class=\"greek\">θυμό</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμοιάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμοιάζω</span> (<span class=\"greek\">ὅμοιος</span> ± <span class=\"greek\">άζω</span>; somente como variante de leitura em Mt e Mk), ser semelhante, parecer-se, com dativo (Leontius 43 p. 88, 6 <span class=\"greek\">τὸ</span> <span class=\"greek\">παιδίον</span> <span class=\"greek\">ὁμοιάζον</span> <span class=\"greek\">αὐτῷ</span>): <span class=\"greek\">τάφοις</span> <span class=\"greek\">κεκονιαμένοις</span>, sepulcros caiados, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:27</a>, variante de leitura. Em emprego absoluto: <span class=\"greek\">ἡ</span> <span class=\"greek\">λαλιά</span> <span class=\"greek\">σου</span> <span class=\"greek\">ὁμοιάζει</span>, tua maneira de falar é semelhante (subentende-se: <span class=\"greek\">τῇ</span> <span class=\"greek\">λαλιᾷ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Γαλιλαίων</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.73\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:73</a>, variante de leitura; igualmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.70\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:70</a>, variante de leitura.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0254-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμοιοπαθής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμοιοπαθής</span>, <span class=\"greek\">ές</span> (<span class=\"greek\">ὅμοιος</span>, <span class=\"greek\">πάσχω</span>; Pla., Rep. 3, 409b, Tim. 45c; Theophr., HP 5, 7, 2; Wsd 7:3; 4 Macc 12:13; Philo, Conf. Lingu. 7; Just.; Tat. 35, 2), relativo a experimentar condições ou sentimentos semelhantes, da mesma natureza, com <span class=\"greek\">τινί</span>, que alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:17</a>.—DELG s.v. <span class=\"greek\">ὅμοιο</span>. M-M. TW.</p></section></article>"};
